import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as t}from"./chunks/Tags.BJ536pW3.js";import{c as l,o as r,j as o,G as a,ae as s,a as n}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"Whole Milk for Healthy Kids Act of 2025","description":"","frontmatter":{"legisId":"2026-01-14-whole-milk-for-healthy-kids-act-of-2025","title":"Whole Milk for Healthy Kids Act of 2025","displayTitle":"Whole Milk for Healthy Kids Act of 2025","lawNumber":"119-69","billNumber":"S. 222","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ69.xml","publishDate":"2026-01-14T00:00:00-05:00","industries":["education","agriculture","healthcare"],"agencies":[],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Whole Milk for Healthy Kids Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-01-14-whole-milk-for-healthy-kids-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Whole Milk for Healthy Kids Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-01-14-whole-milk-for-healthy-kids-act-of-2025\\",\\"datePublished\\":\\"2026-01-14T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-01-14-whole-milk-for-healthy-kids-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-01-14-whole-milk-for-healthy-kids-act-of-2025.md","filePath":"congress-bills/2026-01-14-whole-milk-for-healthy-kids-act-of-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-01-14-whole-milk-for-healthy-kids-act-of-2025.md"},m=Object.assign(d,{setup(c){return(f,e)=>(r(),l("div",null,[e[0]||(e[0]=o("h1",{id:"whole-milk-for-healthy-kids-act-of-2025",tabindex:"-1"},[n("Whole Milk for Healthy Kids Act of 2025 "),o("a",{class:"header-anchor",href:"#whole-milk-for-healthy-kids-act-of-2025","aria-label":'Permalink to "Whole Milk for Healthy Kids Act of 2025"'},"​")],-1)),a(i),a(t,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Wednesday, January 14, 2026. Public Law 119-69, S. 222.</p><p><strong>Headline:</strong> Schools in the national school lunch program may offer whole and reduced-fat milk alongside other milk and qualifying nondairy choices.</p><p><strong>Why it matters:</strong> The law expands beverage options for students while maintaining federal nutrition standards and strengthening food-allergy training.</p><p><strong>What the law does:</strong></p><ul><li>Requires participating schools to offer a variety of milk options.</li><li>Allows whole, reduced-fat, low-fat, or fat-free milk, including flavored, unflavored, organic, nonorganic, and lactose-free varieties.</li><li>Permits nutritionally equivalent nondairy beverages meeting federal standards for calcium, protein, vitamin A, and vitamin D.</li><li>Excludes milk fat from the federal limit on a school meal’s average saturated fat content.</li><li>Allows a physician, parent, or legal guardian to support a student’s need for a milk substitute.</li><li>Adds food-allergy prevention, recognition, and response practices to training for local school food-service personnel.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Students and families participating in the national school lunch program.</li><li>Participating schools and local school food-service personnel.</li><li>Milk and qualifying nondairy beverage providers.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Students may have access to a broader range of dairy and nondairy beverages at school.</li><li>Families may support a student’s request for a milk substitute without relying solely on a physician.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="whole-milk-for-healthy-kids-act-of-2025-1" tabindex="-1">Whole Milk for Healthy Kids Act of 2025 <a class="header-anchor" href="#whole-milk-for-healthy-kids-act-of-2025-1" aria-label="Permalink to &quot;Whole Milk for Healthy Kids Act of 2025&quot;">​</a></h3><p>This law allows schools in the national school lunch program to offer whole, reduced-fat, low-fat, or fat-free milk, including flavored, unflavored, organic, nonorganic, and lactose-free options. It also permits nutritionally equivalent nondairy beverages and adds food-allergy prevention and response information to training for local school food-service personnel.</p><p><strong>Key takeaways:</strong></p><ul><li>Participating schools must offer students a variety of milk options.</li><li>Schools may serve whole, reduced-fat, low-fat, or fat-free milk, including flavored, unflavored, organic, nonorganic, and lactose-free varieties.</li><li>Schools may offer nondairy beverages that meet federal nutrition standards, including required levels of calcium, protein, vitamin A, and vitamin D.</li><li>Milk fat does not count toward the federal limit on a school meal’s average saturated fat content.</li><li>A physician, parent, or legal guardian may support a student’s need for a milk substitute.</li><li>Training for local school food-service personnel must cover best practices for preventing, recognizing, and responding to food-related allergic reactions.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ69.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ69.xml</a></p>',15))]))}});export{u as __pageData,m as default};
